const Search={
  async open(){UI.screen('searchScreen');if(!state.searchIndex.length)Search.rebuildIndex();setTimeout(()=>$('searchInput')?.focus(),50)},
  openWith(encoded){Search.open();const q=decodeURIComponent(encoded);$('searchInput').value=q;Search.run(q)},
  rebuildIndex(){const idx=[];state.allClients.forEach(c=>{const inv=invoiceValues(c),base=normalize([c.client,...inv].join(' '));idx.push({type:'client',title:c.client,search:base,data:c});inv.forEach(v=>idx.push({type:'invoice',title:v,search:normalize(v+' '+c.client),data:c}))});state.searchIndex=idx;$('searchIndexStatus')&&($('searchIndexStatus').textContent=`${arNum(idx.length)} عميل/فاتورة مفهرسة`)},
  run(q){q=String(q??$('searchInput').value).trim();clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>Search.render(q),70)},
  async render(q){const wrap=$('searchResults');if(!q){wrap.innerHTML='<div class="card empty">اكتب اسم العميل أو رقم الفاتورة</div>';return}const nq=normalize(q),tokens=nq.split(' ').filter(Boolean);let hits=state.searchIndex.map(x=>{const exact=x.search===nq?100:x.search.startsWith(nq)?75:tokens.every(t=>x.search.includes(t))?55:x.search.includes(nq)?45:0;return {x,score:exact}}).filter(h=>h.score).sort((a,b)=>b.score-a.score).slice(0,40).map(h=>h.x);const seen=new Set();hits=hits.filter(h=>{const k=String(h.data.client||h.title||'');if(seen.has(k))return false;seen.add(k);return true});wrap.innerHTML=hits.length?hits.map(Search.card).join(''):'<div class="card empty">لا توجد نتائج محلية، جاري التحقق من الخادم...</div>';if(!hits.length&&q.length>=2){clearTimeout(state.searchServerTimer);state.searchServerTimer=setTimeout(()=>Search.server(q),180)}},
  card(h){const c=h.data,inv=invoiceText(c);return `<div class="card search-result-card"><div class="result-row"><div><div class="result-type">${h.type==='invoice'?'فاتورة':'عميل'}</div><div class="result-title">${h.type==='invoice'?'فاتورة '+esc(h.title):esc(c.client)}</div><div class="result-sub">${h.type==='invoice'?`العميل: ${esc(c.client)} · `:''}الفواتير: ${esc(inv)} · المتبقي ${num(c.remaining)}</div></div><div class="result-actions no-print"><button class="soft-btn" onclick="Orders.openEncoded('${encodeURIComponent(c.client)}','active')">الطلبية</button><button class="soft-btn" onclick="ClientProfile.openEncoded('${encodeURIComponent(c.client)}')">👤 ملف العميل</button></div></div></div>`},
  async server(q){try{const r=await Api.search(q);if(normalize($('searchInput')?.value||'')!==normalize(q))return;const data=Api.readData(r)||[],known=new Map(state.allClients.map(c=>[String(c.client),c]));data.forEach(x=>{const name=typeof x==='string'?x:fields(x,['client','name','customer']);if(!name)return;if(!known.has(String(name))){const row=typeof x==='string'?{client:x}:x;state.allClients.push(row);known.set(String(name),row)}else if(typeof x==='object'&&x.invoices&&!known.get(String(name)).invoices){known.get(String(name)).invoices=x.invoices}});Search.rebuildIndex();Search.render(q)}catch(_){if(normalize($('searchInput')?.value||'')===normalize(q)&&!state.searchIndex.some(x=>x.search.includes(normalize(q))))$('searchResults').innerHTML='<div class="card empty">لا توجد نتائج مطابقة</div>'}}
};
function money(v){return num(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}
function invoiceDate(){const d=new Date();return `${d.getFullYear()}/${d.getMonth()+1}/${d.getDate()}`}
function invoiceItemDescription(row,priceRec){const base=String(priceRec?.description||fields(row,['description','itemDescription','itemName','item','name','productName','product'])||`موديل ${row.model}`).trim();const size=String(priceRec?.size||fields(row,['size','sizes','sizeText','measure'])||'').trim();return size&&!normalize(base).includes(normalize(size))?`${base} مقاس ${size}`:base}
function readyInvoiceQty(row){const rem=effectiveRemaining(row);const explicit=fields(row,['readyQty','readyQuantity','deliverableQty','availableToDeliver','availableQty']);if(explicit!==''&&num(explicit)>0)return rem>0?Math.min(rem,num(explicit)):num(explicit);return rem>0?rem:Math.max(0,num(fields(row,['required','qty','requested'])))}
function tripletWords(n){n=Math.floor(n);if(!n)return '';const ones=['','واحد','اثنان','ثلاثة','أربعة','خمسة','ستة','سبعة','ثمانية','تسعة','عشرة','أحد عشر','اثنا عشر','ثلاثة عشر','أربعة عشر','خمسة عشر','ستة عشر','سبعة عشر','ثمانية عشر','تسعة عشر'];const tens=['','','عشرون','ثلاثون','أربعون','خمسون','ستون','سبعون','ثمانون','تسعون'];const hundreds=['','مائة','مائتان','ثلاثمائة','أربعمائة','خمسمائة','ستمائة','سبعمائة','ثمانمائة','تسعمائة'];const parts=[];const h=Math.floor(n/100),r=n%100;if(h)parts.push(hundreds[h]);if(r){if(r<20)parts.push(ones[r]);else{const o=r%10,t=Math.floor(r/10);parts.push(o?`${ones[o]} و${tens[t]}`:tens[t])}}return parts.join(' و')}
