function mergeInvoiceRows(rows){const map=new Map();rows.forEach(r=>{const model=String(r?.model??'').trim(),qty=readyInvoiceQty(r);if(!model||qty<=0)return;if(!map.has(model))map.set(model,{...r,model,_invoiceQty:0});map.get(model)._invoiceQty+=qty});return [...map.values()].sort(natural)}
